// Sample data for milestone 1 (screens + sample data). Ported from the design prototype.
// Week of Mon Oct 19 – Sun Oct 25; "today" is Thursday.

export type DayKey = 'mon' | 'tue' | 'wed' | 'thu' | 'fri' | 'sat' | 'sun';
export type DayVariant = 'mon' | 'tue' | 'wed' | 'thu_start' | 'thu_mid' | 'thu_end' | 'fri' | 'sat' | 'sun';
export type ZoneLabel = [text: string, radius: number, startDeg: number, endDeg: number, sweep: 0 | 1];

export interface RideStats { min: number; w: number; wkg: string; pct: number; zone: string }
export interface Day {
  label: string;
  /** kJ burned on the bike */ kj: number;
  /** daily kJ target (0 = rest day) */ tgt: number;
  note: string;
  /** grams eaten */ gP: number; gC: number; gF: number;
  /** gram targets */ TP: number; TC: number; TF: number;
  /** kcal left / of */ left: number; of: number;
  tC: number; tP: number; tF: number;
  ride?: RideStats;
  /** 100 power ticks, 4 W each (0–400 W): [length px, colour] */
  rays?: [number, string][];
  zoneLabels?: ZoneLabel[];
}

